INSERT INTO site_settings (key, value, version)
VALUES ('landing', $json${"hero": {"eyebrow": "Làng nghề truyền thống · Từ 1950", "titleTop": "Nón Lá", "titleAccent": "Hồn Việt", "text": "Từng chiếc nón đan bằng lá cọ non và vành tre vót tay, qua bàn tay nghệ nhân. Che nắng, che mưa — và che cả một miền ký ức.", "primaryCta": "Khám phá bộ sưu tập", "secondaryCta": "Câu chuyện làng nghề"}, "story": {"eyebrow": "Câu chuyện", "title": {"before": "Mỗi chiếc nón là một", "accent": "bài thơ", "after": "đan bằng tay"}, "text": "Từ những buổi sớm hái lá cọ còn đẫm sương, đến đêm khuya chằm từng mũi chỉ dưới đèn dầu — nón lá là kết tinh của kiên nhẫn và tình yêu quê hương. Chúng tôi giữ trọn từng công đoạn thủ công để bạn đội lên một chiếc nón thật sự có hồn.", "bigWord": "70", "badgeText": "NÓN LÁ • THỦ CÔNG • VIỆT NAM •", "imageUrl": "https://images.pexels.com/photos/13757395/pexels-photo-13757395.jpeg?auto=compress&cs=tinysrgb&dpr=1&h=800&w=1100", "imageAlt": "Nghệ nhân làm nón lá", "stats": [{"value": 70, "suffix": "+", "label": "năm giữ nghề"}, {"value": 16, "suffix": "", "label": "vành tre vót tay"}, {"value": 12000, "suffix": "+", "label": "khách yêu mến"}]}, "process": {"eyebrow": "Quy trình thủ công", "title": {"before": "Từ chiếc lá đến", "accent": "chiếc nón", "after": ""}, "steps": [{"icon": "🌿", "title": "Hái lá & phơi sương", "text": "Chọn lá cọ non, phơi sương đêm rồi phơi nắng nhẹ cho lá giữ màu xanh ngà.", "duration": "2 ngày"}, {"icon": "♨️", "title": "Ủi lá phẳng mịn", "text": "Lá được hơ than hồng, ủi phẳng bằng tay để mặt lá bóng và không giòn gãy.", "duration": "4 giờ"}, {"icon": "🎋", "title": "Uốn vành, dựng khung", "text": "Tre già chẻ mỏng, vót tròn và uốn thành 16 vành lớn dần theo hình chóp.", "duration": "1 ngày"}, {"icon": "🧵", "title": "Chằm nón từng mũi", "text": "Ngồi chằm từng mũi chỉ tơ nhỏ đều, vừa chắc vừa kín để nón mềm mà không xệ.", "duration": "1–2 ngày"}, {"icon": "✨", "title": "Quét dầu & gắn quai", "text": "Phủ lớp dầu bóng chống nước, gắn quai lụa và hoạ tiết hoàn thiện chiếc nón.", "duration": "nửa ngày"}]}, "testimonials": {"eyebrow": "Khách hàng nói gì", "items": [{"quote": "Nón nhẹ tênh, quai lụa mềm. Đội đi chụp ảnh áo dài ở phố cổ ai cũng hỏi mua ở đâu.", "name": "Thu Hà", "where": "Hà Nội · Nón Quai Thao", "imageUrl": "https://images.pexels.com/photos/31204939/pexels-photo-31204939.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=800&w=600", "caption": "Áo dài & Nón quai thao"}, {"quote": "Mẫu nón vẽ sen đẹp như một món quà nghệ thuật. Mình đã đặt thêm 5 chiếc tặng bạn bè nước ngoài.", "name": "Minh Châu", "where": "Đà Nẵng · Nón Vẽ Sen", "imageUrl": "https://images.pexels.com/photos/30292693/pexels-photo-30292693.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=800&w=600", "caption": "Nón vẽ sen hồng"}, {"quote": "Đóng gói cẩn thận, giao vào Sài Gòn không móp méo. Vành đều, lá khít — đúng chất nón làng nghề.", "name": "Ngọc Anh", "where": "TP.HCM · Nón Truyền Thống", "imageUrl": "https://images.pexels.com/photos/11167437/pexels-photo-11167437.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=800&w=600", "caption": "Sắc vàng dưới nắng"}, {"quote": "Chiếc nón bài thơ làm mình nhớ bà ngoại ở Huế. Chỉ mua một lần mà mê luôn.", "name": "Khánh Linh", "where": "Huế · Nón Bài Thơ", "imageUrl": "https://images.pexels.com/photos/32974509/pexels-photo-32974509.jpeg?auto=compress&cs=tinysrgb&fit=crop&h=800&w=600", "caption": "Nét duyên xứ Huế"}]}, "order": {"eyebrow": "Đặt hàng", "titleTop": "Đội nón Việt,", "titleAccent": "mang hồn quê", "titleBottom": "đi xa", "text": "Giao hàng toàn quốc, đóng gói chống móp và đổi trả theo chính sách của cửa hàng."}}$json$::jsonb, 1)
